// ContractCheck is one check you wrote. The body is a plain named
// function; which field you put it in decides what it is handed.
//
// Every field down to Argued is documented on [suite.Row], which is
// what this becomes when the run binds it. The fields after them are this
// interface's own — they name the types its methods draw — and are
// documented here.
type ContractCheck struct {
	Method       string
	Name         string
	Claim        string
	Run          func(tb testing.TB, s Contract, fx ContractFixture)
	RunWith      func(tb testing.TB, sub ContractSubject, fx ContractFixture)
	Class        suite.Class
	Needs        suite.Caps
	ProvenBy     ContractDefect
	ProvenReason string
	Argued       string

	// Prop is a body whose inputs are drawn rather than fixed, run many
	// times with the draws shrunk on failure. Report through the PropT
	// and not through a testing.TB: shrinking works by replaying draws, and
	// a failure raised anywhere else is one the run cannot narrow.
	//
	// Requires Method, like Run.
	Prop func(rt *PropT, s Contract, fx ContractFixture)

	// PropTrigger is Prop with Trigger's own argument already drawn
	// from the pool the generated checks draw it from — so an override you
	// set on the run reaches your property too. Fixes the check's scope to
	// Trigger, so leave Method empty.
	PropTrigger func(rt *PropT, s Contract, value watcher.Value)
}

// contractMethods is the interface's method names — see
// [suite.NewNameSet] for what they catch.
var contractMethods = suite.NewNameSet("Contract", contractWatch, contractTrigger)

// bind converts one of your checks into the form the runner uses, tying
// it to this run's sample inputs — which is what lets a check you wrote
// see the same values, and the same overrides, as the generated ones.
func (c ContractCheck) bind(
	fx ContractFixture,
) (suite.Check[Contract], error) {
	b := suite.BindRow(suite.Row[Contract, ContractFixture]{
		Method: c.Method, Name: c.Name, Claim: c.Claim,
		Run: c.Run, RunWith: c.RunWith,
		Class: c.Class, Needs: c.Needs,
		Proven: c.ProvenBy != nil, ProvenReason: c.ProvenReason, Argued: c.Argued,
	}, fx, contractMethods)
	b.Offers("Prop, PropTrigger")
	if fn := c.Prop; fn != nil {
		b.ScopedWith("Prop", c.Method, func(tb testing.TB, sub suite.Subject[Contract]) {
			model.Check(tb, func(rt *PropT) {
				fn(rt, sub.New(tb), fx)
			})
		})
	}
	if fn := c.PropTrigger; fn != nil {
		b.Fixed(suite.MethodID(contractTrigger, c.Name),
			func(tb testing.TB, sub suite.Subject[Contract]) {
				model.Check(tb, func(rt *PropT) {
					fn(rt, sub.New(tb), contractModelValues(fx).Draw(rt, "value"))
				})
			})
	}
	return b.Seal(c.Method)
}

