// --- Contract's model tier -------------------------------------------
//
// Random sequences of Contract's methods, run against every subject and
// something that judges them from outside. The rows on the run surface
// above carry it, and ContractSuite.Without declines any of them by name.
//
//	Reference: the subject's own factory — the reader speaks (string → go.thesmos.sh/testkit/conformance/corpus/iface/contract/watcher.Subscription) where the keyed writer takes (string, go.thesmos.sh/testkit/conformance/corpus/iface/contract/watcher.Value),
//	           so a second instance driven identically stands in: twins must
//	           agree, which catches nondeterminism and hidden shared state but
//	           not a subject wrong the same way twice; ref= raises the floor
//	Sequences: Trigger (compositewriter)
//	Values:    the fixture pair blended with arbitrary draws
//	Not driven:
//	           Watch — answers a live handle only identity could compare
//	Not bound:
//	           AUTO-WRITE-OBSERVABLE — Read closes over Watch, which reads (string → go.thesmos.sh/testkit/conformance/corpus/iface/contract/watcher.Subscription) beside pools of (string, go.thesmos.sh/testkit/conformance/corpus/iface/contract/watcher.Value)
//	           contract differential — the reference is the subject's own factory, whose comparison already rides each law leg's actions; alone it catches nondeterminism and nothing a second instance shares
//	           contract differential — every driven method here answers an error and nothing else, so both sides return nil for every call a correct subject makes and the comparison has nothing to disagree about

// contractModelKeys is the key pool every key slot draws from.
//
// Two keys, and deliberately not more: collision density is what makes a
// read revisit a write and an overwrite land on held state. A wide key
// pool would pass every comparison over a history that never collides.
func contractModelKeys(fx ContractFixture) *model.Generator[string] {
	// Widened unconditionally: this run emits no config, so there is no
	// pool a consumer could have narrowed and nothing to gate on. The
	// provenance argument applies to a pool somebody passed, and nobody
	// can pass one here.
	return legs.Blend(true,
		model.SampledFrom([]string{fx.Key(), fx.KeyOther()}),
		func(s string) string { return s },
	)
}

// contractModelValues is the value pool every value slot draws from.
//
// The fixture pair blended with arbitrary draws: the pair keeps identical
// rewrites frequent, the wide arm reaches values no fixture spells, and
// nothing in the claims licenses refusing either.
func contractModelValues(fx ContractFixture) *model.Generator[watcher.Value] {
	bodies := model.OneOf(
		model.SampledFrom([]watcher.Value{fx.Value(), fx.ValueOther()}),
		model.Make[watcher.Value](),
	)
	return bodies
}

// contractModelActions is the operation vocabulary both legs drive.
//
// One constructor per method shape, from the engine's action set rather
// than hand-written closures: the constructors record inputs and outputs
// into the trace a law reads, compare the two sides the same way for every
// action, and shrink a failing sequence to the shortest one that still
// fails.
func contractModelActions(fx ContractFixture) []model.Action[Contract] {
	keys := contractModelKeys(fx)
	values := contractModelValues(fx)
	out := []model.Action[Contract]{
		action.CompositeWriter("Trigger", keys, values,
			func(ctx context.Context, s watcher.Contract, k string, v watcher.Value) error {
				return s.Trigger(ctx, k, v)
			}),
	}
	return out
}

// contractAssertWatcherReturnsOnChange binds AUTO-WATCHER-RETURNS-ON-CHANGE over the shared sequences.
//
// One law, and the run's only oracle — see [legs.Law]
// for why the differential is off on every law leg.
func contractAssertWatcherReturnsOnChange(
	tb testing.TB,
	sub suite.Subject[Contract],
	fx ContractFixture,
) {
	tb.Helper()
	keys := contractModelKeys(fx)
	values := contractModelValues(fx)

	buildRef, tier := legs.Reference(tb, sub, func() Contract { return sub.New(tb) })
	sub.NoteTier(tier)
	legs.Law(tb, sub,
		func() Contract { return sub.New(tb) }, buildRef,
		contractModelActions(fx),
		[]law.Law[Contract]{
			law.WatcherReturnsOnChange[watcher.Contract, watcher.Subscription, string, watcher.Value]{
				Watch: func(rt *model.T, s watcher.Contract, k string) (watcher.Subscription, error) {
					return s.Watch(rt.Context(), k)
				},
				Mutate: func(rt *model.T, s watcher.Contract, k string, v watcher.Value) error {
					return s.Trigger(rt.Context(), k, v)
				},
				Next: func(w watcher.Subscription, timeout time.Duration) (watcher.Value, bool) {
					return w.Next(timeout)
				},
				Stop: func(w watcher.Subscription) {
					w.Stop()
				},
				Keys:   keys,
				Values: values,
			},
		})
}

